function icon(name, cls = '') {
  return `<svg class="i ${cls}" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name] || ICONS.info}</svg>`;
}
function logo(cls = '') {
  return `<span class="logo ${cls}"><svg viewBox="0 0 24 24" aria-hidden="true">${ICONS.logoMark}</svg></span>`;
}
